    ('ovn-nog-077', '5d3819711cd679e23167e6b8e22930c1', 'b8c84fc2f9d5205699a392a0b50434bf', '81df0bc0cbe60bf10e3db032e8625f32', 0, '95041ad96dbc892a8a4061b6d16a8835'),
    ('ovn-nog-078', '5d3819711cd679e23167e6b8e22930c1', 'eb09db4dd9a72d7b612c548a2d2e1739', '81df0bc0cbe60bf10e3db032e8625f32', 4, 'cc84801f158ced0b82daba3d3d120698'),
    ('ovn-nog-079', '5d3819711cd679e23167e6b8e22930c1', '3415d0261294692f0a02be405d931ce0', '81df0bc0cbe60bf10e3db032e8625f32', 3, 'c5726b16e9f3988ccf1ea851aec26fd4'),
    ('ovn-nog-080', '5d3819711cd679e23167e6b8e22930c1', '1c50c8feef6523524ce5dd7db377eead', '81df0bc0cbe60bf10e3db032e8625f32', 2, '3f9a679acd7ccad8d42ee156a038e98a')
    ) as v(id, prompt_md5, passage_md5, options_md5, correct_index, explain_md5)
  loop
    if exists (select 1 from public.questions q where q.id = fix.id) then
      present := present + 1;
    end if;
    if exists (
      select 1 from public.questions q
       where q.id = fix.id
         and q.status = 'draft'
         and q.verification = 'agreed'
         and md5(q.prompt) = fix.prompt_md5
         and md5(q.passage) is not distinct from fix.passage_md5
         and md5(q.options::text) = fix.options_md5
         and q.correct_index = fix.correct_index
         and md5(q.explain) = fix.explain_md5
    ) then
      ok := ok || fix.id;
    elsif exists (select 1 from public.questions q where q.id = fix.id and q.status <> 'published') then
      skipped := skipped || fix.id;
    end if;
  end loop;

  if present = 0 then
    raise notice '0025: de nya frågorna finns inte i databasen; inget görs.';
    return;
  end if;

  update public.questions set status = 'published' where id = any(ok);

  raise notice '0025: % publicerade, % hoppades över: %', coalesce(array_length(ok, 1), 0),
    coalesce(array_length(skipped, 1), 0), array_to_string(skipped, ', ');
end
